WITH s AS (
  SELECT v.id AS vid FROM walk_vertices v JOIN metro_stations m ON m.name='鼓楼'
  ORDER BY v.geom <-> m.geom LIMIT 1
), dd AS (
  SELECT node, agg_cost FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT vid FROM s), 800, directed := false)
), rest AS (
  SELECT p.id, p.name, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> p.geom LIMIT 1) AS vid
  FROM pois p WHERE p.subtype='restaurant'
)
SELECT count(*) AS n_reachable, count(*) FILTER (WHERE dd.agg_cost IS NOT NULL) AS n_joined
FROM rest LEFT JOIN dd ON dd.node = rest.vid;

WITH s AS (
  SELECT v.id AS vid FROM walk_vertices v JOIN metro_stations m ON m.name='鼓楼'
  ORDER BY v.geom <-> m.geom LIMIT 1
), dd AS (
  SELECT node, agg_cost FROM pgr_drivingDistance('SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges', (SELECT vid FROM s), 800, directed := false)
), rest AS (
  SELECT p.id, p.name, p.geom, (SELECT v.id FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> p.geom LIMIT 1) AS vid
  FROM pois p WHERE p.subtype='restaurant'
)
SELECT rest.name, round(dd.agg_cost::numeric,1) AS walk_m,
       round(ST_Distance(rest.geom::geography, (SELECT geom::geography FROM metro_stations WHERE name='鼓楼'))::numeric,1) AS straight_m
FROM rest JOIN dd ON dd.node = rest.vid
ORDER BY dd.agg_cost;

