WITH r AS (
  SELECT ST_PointOnSurface(geom) AS p FROM residential_areas WHERE name='银城东苑' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id, v.in_main, v.component, ST_Distance(v.geom::geography, r.p::geography) AS snap_m
  FROM walk_vertices v, r ORDER BY v.geom <-> r.p LIMIT 1
), sv_main AS (
  SELECT v.id, ST_Distance(v.geom::geography, r.p::geography) AS snap_m
  FROM walk_vertices v, r WHERE v.in_main ORDER BY v.geom <-> r.p LIMIT 1
), st AS (
  SELECT m.id, m.name, ST_Distance(m.geom::geography, r.p::geography) AS straight_m
  FROM metro_stations m, r ORDER BY m.geom <-> r.p LIMIT 5
)
SELECT (SELECT id FROM sv) AS snap_vertex, (SELECT in_main FROM sv) AS snap_in_main,
       (SELECT component FROM sv) AS snap_component, (SELECT snap_m FROM sv) AS snap_dist_m,
       (SELECT id FROM sv_main) AS main_vertex, (SELECT snap_m FROM sv_main) AS main_snap_m,
       (SELECT json_agg(json_build_object('name',name,'straight_m',round(straight_m::numeric,1))) FROM st) AS nearest_stations;

WITH r AS (
  SELECT ST_PointOnSurface(geom) AS p FROM residential_areas WHERE name='银城东苑' ORDER BY id LIMIT 1
), sv AS (
  SELECT v.id FROM walk_vertices v, r WHERE v.in_main ORDER BY v.geom <-> r.p LIMIT 1
), dd AS (
  SELECT node, agg_cost FROM pgr_drivingDistance(
    'SELECT id, source, target, cost_m AS cost, cost_m AS reverse_cost FROM walk_edges',
    (SELECT id FROM sv), 3000, directed := false)
), st AS (
  SELECT m.id, m.name, v.id AS vid, ST_Distance(v.geom::geography, m.geom::geography) AS snap_m
  FROM metro_stations m
  JOIN LATERAL (SELECT v.id, v.geom FROM walk_vertices v WHERE v.in_main ORDER BY v.geom <-> m.geom LIMIT 1) v ON true
)
SELECT st.name, round(min(dd.agg_cost)::numeric,1) AS walk_m, round((min(dd.agg_cost)/80.0)::numeric,1) AS walk_min
FROM st JOIN dd ON dd.node = st.vid
GROUP BY st.name ORDER BY walk_m LIMIT 5;

